import{_ as a,C as r,o,c as s,ah as e,E as i}from"./chunks/framework.DuX8SFU5.js";const _=JSON.parse('{"title":"am_node_usb_joystick","description":"","frontmatter":{},"headers":[],"relativePath":"am_node_v2/firmware_am_node_usb_joystick.md","filePath":"am_node_v2/firmware_am_node_usb_joystick.md"}'),n={name:"am_node_v2/firmware_am_node_usb_joystick.md"};function u(c,t,m,l,h,p){const d=r("AssetImage");return o(),s("div",null,[t[0]||(t[0]=e('<h1 id="am-node-usb-joystick" tabindex="-1">am_node_usb_joystick <a class="header-anchor" href="#am-node-usb-joystick" aria-label="Permalink to &quot;am_node_usb_joystick&quot;">​</a></h1><p>Плата: <a href="./">AM_NODE_V2</a>, исполнение H7.</p><p>Прошивка принимает из шины CAN команды джойстиков <a href="./../am_joystick/">AM_JOYSTICK</a> и отдаёт их компьютеру по USB как один HID-джойстик. Драйвер не нужен: Windows, Linux и macOS видят обычный игровой контроллер, браузер — через Gamepad API. Так джойстики стенда можно подключить к компьютеру без адаптера CAN и без ROS.</p><h2 id="usb" tabindex="-1">USB <a class="header-anchor" href="#usb" aria-label="Permalink to &quot;USB&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Значение</th></tr></thead><tbody><tr><td>Класс</td><td>HID, джойстик</td></tr><tr><td>VID:PID</td><td><code>0483:5710</code></td></tr><tr><td>Производитель, изделие</td><td><code>AM</code>, <code>AM USB joystick</code></td></tr><tr><td>Серийный номер</td><td>из UID микроконтроллера, у каждой платы свой</td></tr><tr><td>Отчёт</td><td>8 осей от −32767 до +32767 и 16 кнопок, 18 байт</td></tr><tr><td>Период опроса</td><td>10 мс</td></tr></tbody></table><p>Отчёт уходит при каждом изменении входов; джойстики публикуют 20 раз в секунду. Виртуального COM-порта у этой прошивки нет.</p><h2 id="оси-и-кнопки" tabindex="-1">Оси и кнопки <a class="header-anchor" href="#оси-и-кнопки" aria-label="Permalink to &quot;Оси и кнопки&quot;">​</a></h2><p>Каждая ось и кнопка HID берёт значение из <code>uavcan.equipment.actuator.ArrayCommand</code> со своим <code>actuator_id</code>. По умолчанию раскладка совпадает с номерами джойстиков стенда: левому отдана сотня 1xx, правому — 2xx.</p><table tabindex="0"><thead><tr><th>HID</th><th><code>actuator_id</code> по умолчанию</th><th>Вход джойстика SJ100</th></tr></thead><tbody><tr><td>Ось 1, X</td><td>101</td><td>левый, ось X: +1 — вправо</td></tr><tr><td>Ось 2, Y</td><td>102</td><td>левый, ось Y: вперёд — к минусу оси</td></tr><tr><td>Ось 3, Z</td><td>103</td><td>левый, ролик: +1 — вверх</td></tr><tr><td>Ось 4, Rx</td><td>201</td><td>правый, ось X</td></tr><tr><td>Ось 5, Ry</td><td>202</td><td>правый, ось Y: вперёд — к минусу оси</td></tr><tr><td>Ось 6, Rz</td><td>203</td><td>правый, ролик</td></tr><tr><td>Кнопки 1–3</td><td>121–123</td><td>левый: BT1 (клавиша сбоку), BT2 и BT3 (верхняя и нижняя красные)</td></tr><tr><td>Кнопки 4–7</td><td>111–114</td><td>левый: контакты 1SWA–4SWA (влево, вправо, вперёд, назад)</td></tr><tr><td>Кнопки 8–10</td><td>221–223</td><td>правый: BT1–BT3</td></tr><tr><td>Кнопки 11–14</td><td>211–214</td><td>правый: контакты 1SWA–4SWA</td></tr><tr><td>Оси 7–8, кнопки 15–16</td><td>−1</td><td>не используются</td></tr></tbody></table><p>Команда от −1 до +1 растягивается на всю ось, кнопка нажата при команде от 0,5. В HID ось Y растёт к оператору, поэтому у Y и Ry по умолчанию включён <code>reverse</code>: джойстик вперёд даёт минус оси, как у любого игрового контроллера. Прошивка принимает только команды с <code>command_type</code> 0 (без единиц) и конечным значением.</p><h2 id="потеря-связи" tabindex="-1">Потеря связи <a class="header-anchor" href="#потеря-связи" aria-label="Permalink to &quot;Потеря связи&quot;">​</a></h2><p>Если по входу нет команды дольше <code>usb_joystick.timeout_ms</code> (500 мс), ось встаёт в ноль, а кнопка отпускается. Пропавший джойстик выглядит для компьютера как джойстик в нейтрали, поэтому о потере связи сообщает только статус узла в CAN.</p><table tabindex="0"><thead><tr><th>Health узла</th><th>Когда</th></tr></thead><tbody><tr><td>OK</td><td>по всем включённым входам приходят команды</td></tr><tr><td>WARNING</td><td>хотя бы один включённый вход без команд дольше таймаута</td></tr><tr><td>ERROR</td><td>USB или подписка на <code>ArrayCommand</code> не запустились</td></tr></tbody></table><h2 id="запуск" tabindex="-1">Запуск <a class="header-anchor" href="#запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><ol><li>Собрать прошивку: <code>make am_node_h7_usb_joystick</code>.</li><li>Загрузить её через загрузчик по CAN, как описано ниже.</li><li>Если на плате до этого стояла другая прошивка, сбросить параметры к значениям по умолчанию (Erase), сохранить их (Store) и перезапустить узел. Параметры лежат во внешней FRAM и после смены прошивки читаются по новой таблице: без сброса входы получат чужие значения, например <code>actuator_id</code> 0.</li><li>Подключить плату к компьютеру кабелем USB-C и подвигать ручку: в системе появится <code>AM USB joystick</code>.</li></ol><h2 id="icd" tabindex="-1">ICD <a class="header-anchor" href="#icd" aria-label="Permalink to &quot;ICD&quot;">​</a></h2><p>The node has the following registers:</p><table tabindex="0"><thead><tr><th>Register name</th><th>Description</th></tr></thead><tbody><tr><td>uavcan.node.id</td><td>Defines a node-ID. Allowed values [0,127].</td></tr><tr><td>uavcan.node.description</td><td>User/integrator-defined, human-readable description of this specific node.</td></tr><tr><td>system.log_level</td><td>Log level. See <a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#loglevel" target="_blank" rel="noreferrer">debug.LogLevel</a> and <a href="https://github.com/OpenCyphal/public_regulated_data_types/blob/master/uavcan/diagnostic/Severity.1.0.dsdl" target="_blank" rel="noreferrer">diagnostic.Severity</a>. 0 - Log everything (DEBUG, INFO, WARNING, ERROR) 1 - Log at least INFO level 2 - Log at least WARNING level 3 - Log at least ERROR level 4 - Disable logging By default 3 to show only realy important messages.</td></tr><tr><td>system.name</td><td>Defines custom node name. If empty, the node will use the default name.</td></tr><tr><td>system.reserved1</td><td>Reservew for parameters crc calculation</td></tr><tr><td>system.reserved2</td><td>Bitmask which switch can terminators (0 - both off, 1 - enables second, 2 - enables first, 3 - enables both). Works only for v3.</td></tr><tr><td>system.reserved3</td><td>Auto, Cyphal/CAN or DroneCAN</td></tr><tr><td>system.reserved4</td><td>Reserved</td></tr><tr><td>crct.bitmask</td><td>Bit mask to enable CircuitStatus features: Bit 1 - enable dev.Temperature with device_id=NODE_ID, Bit 2 - enable 5v publisher, Bit 3 - enable Vin publisher. Bit 4 - enable overvoltage, undervoltage, overcurrent and overheat checks. By default 15 that mean enable all publishers</td></tr><tr><td>usb_joystick.axis1.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID axis 1 (X); -1..+1 spans the whole axis. -1 keeps the axis centred.</td></tr><tr><td>usb_joystick.axis1.reverse</td><td>1 flips the sign of HID axis 1 (X). HID Y and Ry grow towards the operator, so they need it for a joystick whose forward is +1.</td></tr><tr><td>usb_joystick.axis2.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID axis 2 (Y); -1..+1 spans the whole axis. -1 keeps the axis centred.</td></tr><tr><td>usb_joystick.axis2.reverse</td><td>1 flips the sign of HID axis 2 (Y). HID Y and Ry grow towards the operator, so they need it for a joystick whose forward is +1.</td></tr><tr><td>usb_joystick.axis3.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID axis 3 (Z); -1..+1 spans the whole axis. -1 keeps the axis centred.</td></tr><tr><td>usb_joystick.axis3.reverse</td><td>1 flips the sign of HID axis 3 (Z). HID Y and Ry grow towards the operator, so they need it for a joystick whose forward is +1.</td></tr><tr><td>usb_joystick.axis4.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID axis 4 (Rx); -1..+1 spans the whole axis. -1 keeps the axis centred.</td></tr><tr><td>usb_joystick.axis4.reverse</td><td>1 flips the sign of HID axis 4 (Rx). HID Y and Ry grow towards the operator, so they need it for a joystick whose forward is +1.</td></tr><tr><td>usb_joystick.axis5.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID axis 5 (Ry); -1..+1 spans the whole axis. -1 keeps the axis centred.</td></tr><tr><td>usb_joystick.axis5.reverse</td><td>1 flips the sign of HID axis 5 (Ry). HID Y and Ry grow towards the operator, so they need it for a joystick whose forward is +1.</td></tr><tr><td>usb_joystick.axis6.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID axis 6 (Rz); -1..+1 spans the whole axis. -1 keeps the axis centred.</td></tr><tr><td>usb_joystick.axis6.reverse</td><td>1 flips the sign of HID axis 6 (Rz). HID Y and Ry grow towards the operator, so they need it for a joystick whose forward is +1.</td></tr><tr><td>usb_joystick.axis7.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID axis 7 (Slider); -1..+1 spans the whole axis. -1 keeps the axis centred.</td></tr><tr><td>usb_joystick.axis7.reverse</td><td>1 flips the sign of HID axis 7 (Slider). HID Y and Ry grow towards the operator, so they need it for a joystick whose forward is +1.</td></tr><tr><td>usb_joystick.axis8.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID axis 8 (Dial); -1..+1 spans the whole axis. -1 keeps the axis centred.</td></tr><tr><td>usb_joystick.axis8.reverse</td><td>1 flips the sign of HID axis 8 (Dial). HID Y and Ry grow towards the operator, so they need it for a joystick whose forward is +1.</td></tr><tr><td>usb_joystick.button1.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 1, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button2.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 2, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button3.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 3, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button4.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 4, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button5.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 5, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button6.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 6, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button7.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 7, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button8.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 8, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button9.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 9, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button10.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 10, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button11.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 11, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button12.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 12, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button13.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 13, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button14.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 14, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button15.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 15, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.button16.aid</td><td>actuator_id from uavcan.equipment.actuator.ArrayCommand driving HID button 16, pressed from 0.5 up. -1 keeps the button released.</td></tr><tr><td>usb_joystick.timeout_ms</td><td>An axis or button without a command for this long reads as centred or released, and the node reports a warning. The joystick nodes send 20 times a second.</td></tr></tbody></table><blockquote><p>This docs was automatically generated. Do not edit it manually.</p></blockquote><h2 id="обновление-прошивки" tabindex="-1">Обновление прошивки <a class="header-anchor" href="#обновление-прошивки" aria-label="Permalink to &quot;Обновление прошивки&quot;">​</a></h2>',20)),i(d,{name:"bootloader.gif",alt:"Обновление прошивки через bootloader"}),t[1]||(t[1]=e("<p>Прошивка обновляется через bootloader по CAN с помощью GUI-инструмента:</p><ol><li>Подключи плату к питанию и CAN-шине.</li><li>Открой GUI-инструмент и выбери нужный узел.</li><li>Выбери <code>.bin</code> файл прошивки.</li><li>Запусти обновление и дождись завершения загрузки.</li><li>После перезапуска проверь, что узел снова появился в сети.</li></ol><p>Если обновление не начинается, сначала проверь питание, CAN-H/CAN-L, общий GND, терминаторы и отсутствие конфликта <code>uavcan.node.id</code>.</p>",3))])}const y=a(n,[["render",u]]);export{_ as __pageData,y as default};
